import fastcipher

class Solver:
    def solve(self, problem, **kwargs):
        ct, tag = fastcipher.encrypt(
            problem["key"],
            problem["nonce"],
            problem["plaintext"],
            problem["associated_data"] or b"",
        )
        return {"ciphertext": ct, "tag": tag}

