/* AVX2 ChaCha20-Poly1305 (RFC 8439) benchmark */
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static inline uint32_t load32_le(const uint8_t *p) {
    uint32_t v; memcpy(&v, p, 4); return v;
}
static inline void store32_le(uint8_t *p, uint32_t v) { memcpy(p, &v, 4); }

#define ROTL(x, n) (((x) << (n)) | ((x) >> (32 - (n))))

static void chacha20_block(uint32_t out[16], const uint32_t in[16]) {
    uint32_t x[16];
    memcpy(x, in, 64);
    for (int i = 0; i < 10; i++) {
        #define QR(a,b,c,d) \
            x[a]+=x[b]; x[d]^=x[a]; x[d]=ROTL(x[d],16); \
            x[c]+=x[d]; x[b]^=x[c]; x[b]=ROTL(x[b],12); \
            x[a]+=x[b]; x[d]^=x[a]; x[d]=ROTL(x[d],8); \
            x[c]+=x[d]; x[b]^=x[c]; x[b]=ROTL(x[b],7);
        QR(0,4,8,12); QR(1,5,9,13); QR(2,6,10,14); QR(3,7,11,15);
        QR(0,5,10,15); QR(1,6,11,12); QR(2,7,8,13); QR(3,4,9,14);
        #undef QR
    }
    for (int i = 0; i < 16; i++) out[i] = x[i] + in[i];
}

/* 4-way AVX2 ChaCha20. Processes 256 bytes. state counter is incremented by 4. */
static void chacha20_4block(uint8_t *out, uint32_t state[16]) {
    __m128i s0 = _mm_loadu_si128((const __m128i*)(state + 0));
    __m128i s1 = _mm_loadu_si128((const __m128i*)(state + 4));
    __m128i s2 = _mm_loadu_si128((const __m128i*)(state + 8));
    __m128i s3 = _mm_loadu_si128((const __m128i*)(state + 12));

    __m256i x0 = _mm256_broadcastsi128_si256(s0);
    __m256i x1 = _mm256_broadcastsi128_si256(s1);
    __m256i x2 = _mm256_broadcastsi128_si256(s2);
    __m256i x3 = _mm256_set_epi32(
        state[15], state[14], state[13], state[12] + 3,
        state[15], state[14], state[13], state[12] + 1);
    /* Wait, broadcast of 128 into 256 duplicates. We need 4 independent states.
       Use two 256-bit regs? Let's redo with proper 4-way using 128? 
       Actually 4-way needs 16 x __m128i or we pack differently.
       Let me use 8 x __m256i holding pairs? Simpler: 4-way with __m128i is scalar-ish.
       Proper approach: each __m256i holds one state word across 8 lanes, but we only have 4.
       Let's do 8-way? No, 4 blocks = 4 lanes of 128? 
       I'll implement 4-way using __m128i arrays via AVX2 256-bit by doing 8 blocks.
    */
    (void)x0;(void)x1;(void)x2;(void)x3;(void)out;
}

/* 8-block AVX2: each ymm holds one word across 8 blocks */
static inline __m256i rotl256(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static void chacha20_8block(uint8_t *dst, const uint8_t *src, uint32_t state[16], int xor_src) {
    __m256i x[16];
    for (int i = 0; i < 16; i++) {
        x[i] = _mm256_set1_epi32(state[i]);
    }
    /* counters: state[12] + 0..7 */
    x[12] = _mm256_add_epi32(x[12], _mm256_set_epi32(7,6,5,4,3,2,1,0));

    __m256i orig[16];
    for (int i = 0; i < 16; i++) orig[i] = x[i];

    for (int r = 0; r < 10; r++) {
        #define QR(a,b,c,d) \
            x[a] = _mm256_add_epi32(x[a], x[b]); x[d] = rotl256(_mm256_xor_si256(x[d], x[a]), 16); \
            x[c] = _mm256_add_epi32(x[c], x[d]); x[b] = rotl256(_mm256_xor_si256(x[b], x[c]), 12); \
            x[a] = _mm256_add_epi32(x[a], x[b]); x[d] = rotl256(_mm256_xor_si256(x[d], x[a]), 8); \
            x[c] = _mm256_add_epi32(x[c], x[d]); x[b] = rotl256(_mm256_xor_si256(x[b], x[c]), 7);
        QR(0,4,8,12); QR(1,5,9,13); QR(2,6,10,14); QR(3,7,11,15);
        QR(0,5,10,15); QR(1,6,11,12); QR(2,7,8,13); QR(3,4,9,14);
        #undef QR
    }
    for (int i = 0; i < 16; i++) x[i] = _mm256_add_epi32(x[i], orig[i]);

    /* transpose 8x16 matrix of uint32 to sequential blocks.
       Each block is 16 words. Lane k has words of block k.
       Store lane-wise. */
    uint32_t tmp[8][16];
    for (int i = 0; i < 16; i++) {
        uint32_t lane[8];
        _mm256_storeu_si256((__m256i*)lane, x[i]);
        for (int k = 0; k < 8; k++) tmp[k][i] = lane[k];
    }
    if (xor_src) {
        for (int k = 0; k < 8; k++) {
            const uint8_t *s = src + k * 64;
            uint8_t *d = dst + k * 64;
            for (int i = 0; i < 16; i++) {
                uint32_t v = tmp[k][i] ^ load32_le(s + 4*i);
                store32_le(d + 4*i, v);
            }
        }
    } else {
        for (int k = 0; k < 8; k++) {
            for (int i = 0; i < 16; i++) store32_le(dst + k*64 + 4*i, tmp[k][i]);
        }
    }
    state[12] += 8;
}

/* ---- Poly1305 (RFC 8439) ---- */
typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    uint8_t buf[16];
    size_t buf_used;
    uint64_t aad_len;
    uint64_t ct_len;
} poly1305_ctx;

static void poly1305_init(poly1305_ctx *st, const uint8_t key[32]) {
    uint32_t t0 = load32_le(key+0);
    uint32_t t1 = load32_le(key+4);
    uint32_t t2 = load32_le(key+8);
    uint32_t t3 = load32_le(key+12);
    st->r[0] = t0 & 0x3ffffff;
    st->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    st->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    st->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    st->r[4] = (t3 >> 8) & 0x00fffff;
    memset(st->h, 0, sizeof(st->h));
    st->pad[0] = load32_le(key+16);
    st->pad[1] = load32_le(key+20);
    st->pad[2] = load32_le(key+24);
    st->pad[3] = load32_le(key+28);
    st->buf_used = 0;
}

static void poly1305_blocks(poly1305_ctx *st, const uint8_t *m, size_t bytes, uint32_t hibit) {
    const uint32_t r0 = st->r[0], r1 = st->r[1], r2 = st->r[2], r3 = st->r[3], r4 = st->r[4];
    const uint32_t s1 = r1 * 5, s2 = r2 * 5, s3 = r3 * 5, s4 = r4 * 5;
    uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];

    while (bytes >= 16) {
        uint32_t t0 = load32_le(m+0);
        uint32_t t1 = load32_le(m+4);
        uint32_t t2 = load32_le(m+8);
        uint32_t t3 = load32_le(m+12);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
        h2 += ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
        h3 += ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
        h4 += (t3 >> 8) | hibit;

        uint64_t d0 = (uint64_t)h0*r0 + (uint64_t)h1*s4 + (uint64_t)h2*s3 + (uint64_t)h3*s2 + (uint64_t)h4*s1;
        uint64_t d1 = (uint64_t)h0*r1 + (uint64_t)h1*r0 + (uint64_t)h2*s4 + (uint64_t)h3*s3 + (uint64_t)h4*s2;
        uint64_t d2 = (uint64_t)h0*r2 + (uint64_t)h1*r1 + (uint64_t)h2*r0 + (uint64_t)h3*s4 + (uint64_t)h4*s3;
        uint64_t d3 = (uint64_t)h0*r3 + (uint64_t)h1*r2 + (uint64_t)h2*r1 + (uint64_t)h3*r0 + (uint64_t)h4*s4;
        uint64_t d4 = (uint64_t)h0*r4 + (uint64_t)h1*r3 + (uint64_t)h2*r2 + (uint64_t)h3*r1 + (uint64_t)h4*r0;

        uint64_t c;
        c = d0 >> 26; h0 = (uint32_t)d0 & 0x3ffffff; d1 += c;
        c = d1 >> 26; h1 = (uint32_t)d1 & 0x3ffffff; d2 += c;
        c = d2 >> 26; h2 = (uint32_t)d2 & 0x3ffffff; d3 += c;
        c = d3 >> 26; h3 = (uint32_t)d3 & 0x3ffffff; d4 += c;
        c = d4 >> 26; h4 = (uint32_t)d4 & 0x3ffffff; h0 += (uint32_t)c * 5;
        c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;

        m += 16; bytes -= 16;
    }
    st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
}

static void poly1305_finish(poly1305_ctx *st, uint8_t tag[16]) {
    if (st->buf_used) {
        uint8_t block[16] = {0};
        memcpy(block, st->buf, st->buf_used);
        block[st->buf_used] = 1;
        /* process with hibit 0 */
        const uint32_t r0 = st->r[0], r1 = st->r[1], r2 = st->r[2], r3 = st->r[3], r4 = st->r[4];
        const uint32_t s1 = r1 * 5, s2 = r2 * 5, s3 = r3 * 5, s4 = r4 * 5;
        uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];
        uint32_t t0 = load32_le(block+0);
        uint32_t t1 = load32_le(block+4);
        uint32_t t2 = load32_le(block+8);
        uint32_t t3 = load32_le(block+12);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
        h2 += ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
        h3 += ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
        h4 += (t3 >> 8); /* hibit 0 */

        uint64_t d0 = (uint64_t)h0*r0 + (uint64_t)h1*s4 + (uint64_t)h2*s3 + (uint64_t)h3*s2 + (uint64_t)h4*s1;
        uint64_t d1 = (uint64_t)h0*r1 + (uint64_t)h1*r0 + (uint64_t)h2*s4 + (uint64_t)h3*s3 + (uint64_t)h4*s2;
        uint64_t d2 = (uint64_t)h0*r2 + (uint64_t)h1*r1 + (uint64_t)h2*r0 + (uint64_t)h3*s4 + (uint64_t)h4*s3;
        uint64_t d3 = (uint64_t)h0*r3 + (uint64_t)h1*r2 + (uint64_t)h2*r1 + (uint64_t)h3*r0 + (uint64_t)h4*s4;
        uint64_t d4 = (uint64_t)h0*r4 + (uint64_t)h1*r3 + (uint64_t)h2*r2 + (uint64_t)h3*r1 + (uint64_t)h4*r0;
        uint64_t c;
        c = d0 >> 26; h0 = (uint32_t)d0 & 0x3ffffff; d1 += c;
        c = d1 >> 26; h1 = (uint32_t)d1 & 0x3ffffff; d2 += c;
        c = d2 >> 26; h2 = (uint32_t)d2 & 0x3ffffff; d3 += c;
        c = d3 >> 26; h3 = (uint32_t)d3 & 0x3ffffff; d4 += c;
        c = d4 >> 26; h4 = (uint32_t)d4 & 0x3ffffff; h0 += (uint32_t)c * 5;
        c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;
        st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
    }
    uint32_t h0=st->h[0], h1=st->h[1], h2=st->h[2], h3=st->h[3], h4=st->h[4];
    uint32_t c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    uint32_t g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);

    uint32_t mask = (g4 >> 31) - 1;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t f0 = ((uint64_t)h0) | ((uint64_t)h1 << 26) ;
    uint64_t f1 = ((uint64_t)h1 >> 6) | ((uint64_t)h2 << 20);
    uint64_t f2 = ((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14);
    uint64_t f3 = ((uint64_t)h3 >> 18) | ((uint64_t)h4 << 8);
    /* actually standard packing: */
    uint32_t fh0 = h0 | (h1 << 26);
    uint32_t fh1 = (h1 >> 6) | (h2 << 20);
    uint32_t fh2 = (h2 >> 12) | (h3 << 14);
    uint32_t fh3 = (h3 >> 18) | (h4 << 8);

    uint64_t acc0 = (uint64_t)fh0 + st->pad[0];
    uint64_t acc1 = (uint64_t)fh1 + st->pad[1] + (acc0 >> 32);
    uint64_t acc2 = (uint64_t)fh2 + st->pad[2] + (acc1 >> 32);
    uint64_t acc3 = (uint64_t)fh3 + st->pad[3] + (acc2 >> 32);
    store32_le(tag+0, (uint32_t)acc0);
    store32_le(tag+4, (uint32_t)acc1);
    store32_le(tag+8, (uint32_t)acc2);
    store32_le(tag+12, (uint32_t)acc3);
    (void)f0;(void)f1;(void)f2;(void)f3;
}

static void poly_update(poly1305_ctx *st, const uint8_t *m, size_t len) {
    if (st->buf_used) {
        size_t need = 16 - st->buf_used;
        if (len < need) { memcpy(st->buf + st->buf_used, m, len); st->buf_used += len; return; }
        memcpy(st->buf + st->buf_used, m, need);
        poly1305_blocks(st, st->buf, 16, 1u << 24);
        m += need; len -= need; st->buf_used = 0;
    }
    size_t full = len & ~15u;
    if (full) poly1305_blocks(st, m, full, 1u << 24);
    if (len & 15) { memcpy(st->buf, m + full, len & 15); st->buf_used = len & 15; }
}

static void chacha20_xor(uint8_t *dst, const uint8_t *src, size_t len, const uint8_t key[32], const uint8_t nonce[12], uint32_t counter) {
    uint32_t state[16] = {
        0x61707865, 0x3320646e, 0x79622d32, 0x6b206574,
        load32_le(key+0), load32_le(key+4), load32_le(key+8), load32_le(key+12),
        load32_le(key+16), load32_le(key+20), load32_le(key+24), load32_le(key+28),
        counter, load32_le(nonce+0), load32_le(nonce+4), load32_le(nonce+8)
    };
    uint8_t *d = dst;
    const uint8_t *s = src;
    while (len >= 512) {
        chacha20_8block(d, s, state, 1);
        d += 512; s += 512; len -= 512;
    }
    while (len) {
        uint32_t block[16];
        chacha20_block(block, state);
        state[12]++;
        size_t n = len < 64 ? len : 64;
        uint8_t tmp[64];
        for (int i = 0; i < 16; i++) store32_le(tmp + 4*i, block[i]);
        for (size_t i = 0; i < n; i++) d[i] = s[i] ^ tmp[i];
        d += n; s += n; len -= n;
    }
}

static void aead_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                         const uint8_t *aad, size_t aad_len,
                         const uint8_t *pt, size_t pt_len,
                         uint8_t *ct, uint8_t tag[16]) {
    /* poly key = chacha block 0 */
    uint32_t state[16] = {
        0x61707865, 0x3320646e, 0x79622d32, 0x6b206574,
        load32_le(key+0), load32_le(key+4), load32_le(key+8), load32_le(key+12),
        load32_le(key+16), load32_le(key+20), load32_le(key+24), load32_le(key+28),
        0, load32_le(nonce+0), load32_le(nonce+4), load32_le(nonce+8)
    };
    uint32_t block[16];
    chacha20_block(block, state);
    uint8_t polykey[32];
    for (int i = 0; i < 8; i++) store32_le(polykey + 4*i, block[i]);

    chacha20_xor(ct, pt, pt_len, key, nonce, 1);

    poly1305_ctx pst;
    poly1305_init(&pst, polykey);
    poly_update(&pst, aad, aad_len);
    if (aad_len & 15) {
        uint8_t z[16] = {0};
        poly_update(&pst, z, 16 - (aad_len & 15));
    }
    poly_update(&pst, ct, pt_len);
    if (pt_len & 15) {
        uint8_t z[16] = {0};
