#include <openssl/evp.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

#define MAX_T 8
typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t off, len;
    unsigned int key[8];
    unsigned int nonce[3];
    unsigned char partial_mac[16];
    void *pctx;
    size_t csz;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    unsigned int counter[4] = { (unsigned int)(j->off / 64) + 1, j->nonce[0], j->nonce[1], j->nonce[2] };
    ChaCha20_ctr32(j->ct + j->off, j->pt + j->off, j->len, j->key, counter);
    Poly1305_Init(j->pctx, j->partial_mac); /* key field reused as one-time key storage? no.
       We'll set a dummy and not use poly here. */
    return NULL;
}

/* Parallel chacha + single poly after. */
static void encrypt_par(int nth, const unsigned char keyb[32], const unsigned char nonce[12],
                        const unsigned char *aad, size_t aad_len,
                        const unsigned char *pt, unsigned char *ct, size_t n,
                        unsigned char tag[16], void **pctxs, size_t csz) {
    unsigned int key[8], nc[3];
    memcpy(key, keyb, 32);
    memcpy(nc, nonce, 12);

    /* poly key = first 32 bytes of block 0 */
    unsigned char block0[64];
    unsigned int counter0[4] = {0, nc[0], nc[1], nc[2]};
    unsigned char zeros[64] = {0};
    ChaCha20_ctr32(block0, zeros, 64, key, counter0);

    pthread_t th[MAX_T];
    job_t jobs[MAX_T];
    size_t chunk = (n / nth) & ~63ull;
    if (chunk == 0) chunk = n;
    size_t off = 0;
    int actual = 0;
    for (int i = 0; i < nth; i++) {
        size_t len = (i == nth-1) ? (n - off) : chunk;
        if (i < nth-1) {
            /* keep len multiple of 64 */
        }
        jobs[i].pt = pt; jobs[i].ct = ct; jobs[i].off = off; jobs[i].len = len;
        memcpy(jobs[i].key, key, 32);
        memcpy(jobs[i].nonce, nc, 12);
        off += len;
        actual++;
        if (off >= n) break;
    }
    for (int i = 0; i < actual; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    for (int i = 0; i < actual; i++) pthread_join(th[i], NULL);

    Poly1305_Init(pctxs[0], block0);
    if (aad_len) Poly1305_Update(pctxs[0], aad, aad_len);
    if (aad_len & 15) {
        unsigned char z[16] = {0};
        Poly1305_Update(pctxs[0], z, 16 - (aad_len & 15));
    }
    Poly1305_Update(pctxs[0], ct, n);
    if (n & 15) {
        unsigned char z[16] = {0};
        Poly1305_Update(pctxs[0], z, 16 - (n & 15));
    }
    unsigned char lens[16] = {0};
    uint64_t al = aad_len, cl = n;
    memcpy(lens, &al, 8);
    memcpy(lens+8, &cl, 8);
    Poly1305_Update(pctxs[0], lens, 16);
    Poly1305_Final(pctxs[0], tag);
}

int main() {
    size_t n = 40000UL * 1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0x42, n);
    unsigned char key[32] = {1,2,3,4,5};
    unsigned char nonce[12] = {9,8,7,6,5,4,3,2,1,0,1,2};
    unsigned char aad[32]; memset(aad, 7, 32);
    unsigned char tag[16];
    size_t csz = Poly1305_ctx_size();
    void *pctxs[1]; pctxs[0] = malloc(csz);

    encrypt_par(4, key, nonce, aad, 32, pt, ct, n, tag, pctxs, csz);

    /* verify against EVP */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *ct2 = malloc(n + 16);
    int outl=0, fin=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
    size_t off=0; int total=0;
    while (off < n) {
        int chunk = (n-off) > (1<<30) ? (1<<30) : (int)(n-off);
        EVP_EncryptUpdate(ctx, ct2+off, &outl, pt+off, chunk);
        off += chunk;
    }
    EVP_EncryptFinal_ex(ctx, ct2+n, &fin);
    unsigned char tag2[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    printf("ct match %d\n", memcmp(ct, ct2, n)==0);
    printf("tag match %d\n", memcmp(tag, tag2)==0);
    if (memcmp(ct, ct2, n)) {
        for (size_t i=0;i<n;i++) if (ct[i]!=ct2[i]) { printf("first ct mismatch %zu\n", i); break; }
    }
    printf("tag  "); for (int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
    printf("tag2 "); for (int i=0;i<16;i++) printf("%02x", tag2[i]); printf("\n");

    for (int nth = 2; nth <= 6; nth++) {
        encrypt_par(nth, key, nonce, aad, 32, pt, ct, 4096, tag, pctxs, csz);
        double t0 = now();
        int reps = 3;
        for (int r = 0; r < reps; r++)
            encrypt_par(nth, key, nonce, aad, 32, pt, ct, n, tag, pctxs, csz);
        double dt = now()-t0;
        printf("%d threads aead %.1f MB/s per=%.4f\n", nth, reps*(n/1e6)/dt, dt/reps);
    }
    return 0;
}
