size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

#define NTHREADS 4
#define SEGMENTS 8

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter0;
    unsigned int nonce[3];
    int done;
    pthread_mutex_t mu;
    pthread_cond_t cv;
} seg_t;

static void *chacha_worker(void *arg) {
    seg_t *s = arg;
    unsigned int counter[4] = { s->counter0, s->nonce[0], s->nonce[1], s->nonce[2] };
    ChaCha20_ctr32(s->ct + s->off, s->pt + s->off, s->len, s->key, counter);
    pthread_mutex_lock(&s->mu);
    s->done = 1;
    pthread_cond_signal(&s->cv);
    pthread_mutex_unlock(&s->mu);
    return NULL;
}

static void encrypt(const unsigned char keyb[32], const unsigned char nonce[12],
                    const unsigned char *aad, size_t aad_len,
                    const unsigned char *pt, unsigned char *ct, size_t n,
                    unsigned char tag[16], void *pctx, seg_t *segs) {
    unsigned int key[8], nc[3];
    memcpy(key, keyb, 32);
    memcpy(nc, nonce, 12);

    unsigned char block0[64]={0}, zeros[64]={0};
    unsigned int c0[4] = {0, nc[0], nc[1], nc[2]};
    ChaCha20_ctr32(block0, zeros, 64, key, c0);

    int nseg = SEGMENTS;
    size_t base = (n / nseg) & ~63ull;
    if (base == 0) { nseg = 1; base = n; }
    size_t off = 0;
    pthread_t th[SEGMENTS];
    for (int i = 0; i < nseg; i++) {
        size_t len = (i == nseg-1) ? (n - off) : base;
        segs[i].pt = pt; segs[i].ct = ct;
        segs[i].off = off; segs[i].len = len;
        memcpy(segs[i].key, key, 32);
        segs[i].counter0 = (unsigned int)(off/64) + 1;
        segs[i].nonce[0]=nc[0]; segs[i].nonce[1]=nc[1]; segs[i].nonce[2]=nc[2];
        segs[i].done = 0;
        off += len;
        pthread_create(&th[i], NULL, chacha_worker, &segs[i]);
    }

    Poly1305_Init(pctx, block0);
    if (aad_len) Poly1305_Update(pctx, aad, aad_len);
    if (aad_len & 15) { unsigned char z[16]={0}; Poly1305_Update(pctx, z, 16-(aad_len&15)); }

    for (int i = 0; i < nseg; i++) {
        pthread_mutex_lock(&segs[i].mu);
        while (!segs[i].done) pthread_cond_wait(&segs[i].cv, &segs[i].mu);
        pthread_mutex_unlock(&segs[i].mu);
        Poly1305_Update(pctx, ct + segs[i].off, segs[i].len);
    }
    for (int i = 0; i < nseg; i++) pthread_join(th[i], NULL);

    if (n & 15) { unsigned char z[16]={0}; Poly1305_Update(pctx, z, 16-(n&15)); }
    unsigned char lens[16]={0};
    uint64_t al=aad_len, cl=n;
    memcpy(lens, &al, 8); memcpy(lens+8, &cl, 8);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
}

int main() {
    size_t n = 40000UL*1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0x42, n);
    unsigned char key[32]={1,2,3,4,5};
    unsigned char nonce[12]={9,8,7,6,5,4,3,2,1,0,1,2};
    unsigned char aad[32]; memset(aad, 7, 32);
    unsigned char tag[16];
    void *pctx = malloc(Poly1305_ctx_size()+64);
    seg_t segs[SEGMENTS];
    for (int i = 0; i < SEGMENTS; i++) {
        pthread_mutex_init(&segs[i].mu, NULL);
        pthread_cond_init(&segs[i].cv, NULL);
    }
    encrypt(key, nonce, aad, 32, pt, ct, n, tag, pctx, segs);
    double t0 = now();
    int reps = 5;
    for (int r = 0; r < reps; r++) encrypt(key, nonce, aad, 32, pt, ct, n, tag, pctx, segs);
    double dt = now()-t0;
    printf("pipeline %d segs %.1f MB/s per=%.4f\n", SEGMENTS, reps*(n/1e6)/dt, dt/reps);
    return 0;
}
