    __m256i d1=_mm256_add_epi64(_mm256_add_epi64(a.l[1], b.l[1]), c); c=_mm256_srli_epi64(d1,26); o.l[1]=_mm256_and_si256(d1,mask);
    __m256i d2=_mm256_add_epi64(_mm256_add_epi64(a.l[2], b.l[2]), c); c=_mm256_srli_epi64(d2,26); o.l[2]=_mm256_and_si256(d2,mask);
    __m256i d3=_mm256_add_epi64(_mm256_add_epi64(a.l[3], b.l[3]), c); c=_mm256_srli_epi64(d3,26); o.l[3]=_mm256_and_si256(d3,mask);
    __m256i d4=_mm256_add_epi64(_mm256_add_epi64(a.l[4], b.l[4]), c); c=_mm256_srli_epi64(d4,26); o.l[4]=_mm256_and_si256(d4,mask);
