static inline vlimb load4(const unsigned char *m0, const unsigned char *m1, const unsigned char *m2, const unsigned char *m3) {
    /* load 4 blocks and convert to limbs, hibit set */
    uint32_t t[4][4];
    memcpy(t[0], m0, 16); memcpy(t[1], m1, 16); memcpy(t[2], m2, 16); memcpy(t[3], m3, 16);
    vlimb v;
    uint64_t l0[4], l1[4], l2[4], l3[4], l4[4];
    for (int i=0;i<4;i++) {
        uint32_t t0=t[i][0], t1=t[i][1], t2=t[i][2], t3=t[i][3];
        l0[i] = t0 & 0x3ffffff;
        l1[i] = ((t0>>26)|(t1<<6)) & 0x3ffffff;
        l2[i] = ((t1>>20)|(t2<<12)) & 0x3ffffff;
        l3[i] = ((t2>>14)|(t3<<18)) & 0x3ffffff;
        l4[i] = (t3>>8) | (1u<<24);
    }
    v.l[0]=_mm256_loadu_si256((const __m256i*)l0);
    v.l[1]=_mm256_loadu_si256((const __m256i*)l1);
    v.l[2]=_mm256_loadu_si256((const __m256i*)l2);
    v.l[3]=_mm256_loadu_si256((const __m256i*)l3);
    v.l[4]=_mm256_loadu_si256((const __m256i*)l4);
    return v;
}

static limb5 lane(vlimb v, int k) {
    uint64_t tmp[4];
    limb5 o;
    for (int i=0;i<5;i++) {
        _mm256_storeu_si256((__m256i*)tmp, v.l[i]);
        o.l[i] = (uint32_t)tmp[k];
    }
    return o;
}

/* Broadcast a limb5 into all 4 lanes */
static vlimb broadcast(limb5 a) {
    vlimb v;
    for (int i=0;i<5;i++) v.l[i] = _mm256_set1_epi64x(a.l[i]);
    return v;
}

int main() {
    /* correctness: 4 independent short messages vs scalar */
    unsigned char key[32];
    for (int i=0;i<32;i++) key[i]=i*3+1;
    limb5 r = clamp_r(key);
    unsigned char msg[4][64];
    for (int i=0;i<4;i++) for (int j=0;j<64;j++) msg[i][j]=i*17+j;

    limb5 h[4];
    for (int i=0;i<4;i++) {
        h[i]=(limb5){{0,0,0,0,0}};
        for (int b=0;b<4;b++) { 
            uint32_t t0,t1,t2,t3; memcpy(&t0,msg[i]+16*b,4); memcpy(&t1,msg[i]+16*b+4,4); memcpy(&t2,msg[i]+16*b+8,4); memcpy(&t3,msg[i]+16*b+12,4);
            limb5 m; m.l[0]=t0&0x3ffffff; m.l[1]=((t0>>26)|(t1<<6))&0x3ffffff; m.l[2]=((t1>>20)|(t2<<12))&0x3ffffff; m.l[3]=((t2>>14)|(t3<<18))&0x3ffffff; m.l[4]=(t3>>8)|(1u<<24);
            h[i] = mul_limb((limb5){{h[i].l[0]+m.l[0], h[i].l[1]+m.l[1], h[i].l[2]+m.l[2], h[i].l[3]+m.l[3], h[i].l[4]+m.l[4]}}, r);
        }
    }
    /* vector: process block by block, 4 streams */
    vlimb hv; for (int i=0;i<5;i++) hv.l[i]=_mm256_setzero_si256();
    vlimb rv = broadcast(r);
    for (int b=0;b<4;b++) {
        vlimb mv = load4(msg[0]+16*b, msg[1]+16*b, msg[2]+16*b, msg[3]+16*b);
        hv = vadd(hv, mv);
        hv = vmul(hv, rv);
    }
    int ok = 1;
    for (int i=0;i<4;i++) {
        limb5 g = lane(hv, i);
        for (int k=0;k<5;k++) if (g.l[k] != h[i].l[k]) ok = 0;
    }
    printf("vec match %d\n", ok);

    /* speed: 4 streams of 10 MB each vs openssl one stream */
    size_t n = 10*1024*1024; n &= ~15ull;
    unsigned char *bufs[4];
    for (int i=0;i<4;i++) { bufs[i]=aligned_alloc(64, n); memset(bufs[i], 0xab+i, n); }
    size_t blocks = n/16;
    double t0 = now();
    int reps = 3;
    for (int rep=0; rep<reps; rep++) {
        vlimb hv2; for (int i=0;i<5;i++) hv2.l[i]=_mm256_setzero_si256();
        for (size_t b=0; b<blocks; b++) {
            vlimb mv = load4(bufs[0]+16*b, bufs[1]+16*b, bufs[2]+16*b, bufs[3]+16*b);
            hv2 = vadd(hv2, mv);
            hv2 = vmul(hv2, rv);
        }
        volatile uint32_t sink = (uint32_t)_mm256_extract_epi64(hv2.l[0], 0);
        (void)sink;
    }
    double dt = now()-t0;
    printf("avx2 4-stream poly %.1f MB/s per=%.4f (aggregate)\n", reps*(4*n/1e6)/dt, dt/reps);

    /* openssl single */
    void *ctx = malloc(Poly1305_ctx_size());
    unsigned char tag[16];
    t0 = now();
    for (int rep=0; rep<reps; rep++) {
        Poly1305_Init(ctx, key);
        Poly1305_Update(ctx, bufs[0], n);
        Poly1305_Final(ctx, tag);
    }
    dt = now()-t0;
    printf("openssl single %.1f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);
    return 0;
}
