#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sched.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

#define NTHREADS 6

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter0;
    unsigned int nonce[3];
    atomic_int done;
} seg_t;

typedef struct {
    seg_t *seg;
    atomic_int has_work;
    atomic_int stop;
} worker_t;

static worker_t workers[NTHREADS];

static void *worker_fn(void *arg) {
    worker_t *w = arg;
    for (;;) {
        while (!atomic_load_explicit(&w->has_work, memory_order_acquire)) {
            if (atomic_load_explicit(&w->stop, memory_order_relaxed)) return NULL;
            /* pause */
            _mm_pause();
        }
        seg_t *s = w->seg;
        unsigned int counter[4] = { s->counter0, s->nonce[0], s->nonce[1], s->nonce[2] };
        ChaCha20_ctr32(s->ct + s->off, s->pt + s->off, s->len, s->key, counter);
        atomic_store_explicit(&s->done, 1, memory_order_release);
        atomic_store_explicit(&w->has_work, 0, memory_order_release);
    }
}
#include <immintrin.h>

static void pool_init(void) {
    for (int i = 0; i < NTHREADS; i++) {
        atomic_store(&workers[i].has_work, 0);
        atomic_store(&workers[i].stop, 0);
        pthread_t th;
        pthread_create(&th, NULL, worker_fn, &workers[i]);
        pthread_detach(th);
    }
}

static void encrypt(const unsigned char keyb[32], const unsigned char nonce[12],
                    const unsigned char *aad, size_t aad_len,
                    const unsigned char *pt, unsigned char *ct, size_t n,
                    unsigned char tag[16], void *pctx) {
    unsigned int key[8], nc[3];
    memcpy(key, keyb, 32);
    memcpy(nc, nonce, 12);

    unsigned char block0[64]={0}, zeros[64]={0};
    unsigned int c0[4] = {0, nc[0], nc[1], nc[2]};
    ChaCha20_ctr32(block0, zeros, 64, key, c0);

    int nseg = NTHREADS;
    size_t base = (n / nseg) & ~63ull;
    seg_t segs[NTHREADS];
    size_t off = 0;
    for (int i = 0; i < nseg; i++) {
        size_t len = (i == nseg-1) ? (n - off) : base;
        segs[i].pt = pt; segs[i].ct = ct;
        segs[i].off = off; segs[i].len = len;
        memcpy(segs[i].key, key, 32);
        segs[i].counter0 = (unsigned int)(off/64) + 1;
        segs[i].nonce[0]=nc[0]; segs[i].nonce[1]=nc[1]; segs[i].nonce[2]=nc[2];
        atomic_store_explicit(&segs[i].done, 0, memory_order_relaxed);
        off += len;
        workers[i].seg = &segs[i];
    }
    /* publish all work */
    for (int i = 0; i < nseg; i++)
        atomic_store_explicit(&workers[i].has_work, 1, memory_order_release);

    Poly1305_Init(pctx, block0);
    if (aad_len) Poly1305_Update(pctx, aad, aad_len);
    if (aad_len & 15) { unsigned char z[16]={0}; Poly1305_Update(pctx, z, 16-(aad_len&15)); }

    for (int i = 0; i < nseg; i++) {
        while (!atomic_load_explicit(&segs[i].done, memory_order_acquire)) _mm_pause();
        Poly1305_Update(pctx, ct + segs[i].off, segs[i].len);
    }
    if (n & 15) { unsigned char z[16]={0}; Poly1305_Update(pctx, z, 16-(n&15)); }
    unsigned char lens[16]={0};
    uint64_t al=aad_len, cl=n;
    memcpy(lens, &al, 8); memcpy(lens+8, &cl, 8);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
}

#include <openssl/evp.h>
int main() {
    pool_init();
    size_t n = 40000UL*1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0x42, n);
    unsigned char key[32]={1,2,3,4,5};
    unsigned char nonce[12]={9,8,7,6,5,4,3,2,1,0,1,2};
    unsigned char aad[32]; memset(aad, 7, 32);
    unsigned char tag[16];
    void *pctx = malloc(Poly1305_ctx_size()+64);

    for (int i=0;i<3;i++) encrypt(key, nonce, aad, 32, pt, ct, n, tag, pctx);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *ct2 = malloc(n);
    int outl=0, fin=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
    size_t o=0;
    while (o<n) { int chunk=(n-o)>(1<<30)?(1<<30):(int)(n-o); EVP_EncryptUpdate(ctx, ct2+o, &outl, pt+o, chunk); o+=chunk; }
    EVP_EncryptFinal_ex(ctx, ct2+n, &fin);
    unsigned char tag2[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    printf("match ct %d tag %d\n", memcmp(ct,ct2,n)==0, memcmp(tag,tag2,16)==0);

    double t0 = now();
    int reps = 10;
    for (int r = 0; r < reps; r++) encrypt(key, nonce, aad, 32, pt, ct, n, tag, pctx);
    double dt = now()-t0;
    printf("pool %d threads %.1f MB/s per=%.4f\n", NTHREADS, reps*(n/1e6)/dt, dt/reps);
    return 0;
}
