__attribute__((noinline))
static void xor512(uint8_t *dst, const uint8_t *src, const __m256i base[16], uint32_t counter_base) {
    __m256i x0=base[0],x1=base[1],x2=base[2],x3=base[3];
    __m256i x4=base[4],x5=base[5],x6=base[6],x7=base[7];
    __m256i x8=base[8],x9=base[9],x10=base[10],x11=base[11];
    __m256i x12=_mm256_add_epi32(base[12], _mm256_set_epi32(7,6,5,4,3,2,1,0));
    __m256i x13=base[13],x14=base[14],x15=base[15];
    __m256i o0=x0,o1=x1,o2=x2,o3=x3,o4=x4,o5=x5,o6=x6,o7=x7,o8=x8,o9=x9,o10=x10,o11=x11,o12=x12,o13=x13,o14=x14,o15=x15;
    #define QR(a,b,c,d) a=_mm256_add_epi32(a,b); d=rotl(_mm256_xor_si256(d,a),16); c=_mm256_add_epi32(c,d); b=rotl(_mm256_xor_si256(b,c),12); a=_mm256_add_epi32(a,b); d=rotl(_mm256_xor_si256(d,a),8); c=_mm256_add_epi32(c,d); b=rotl(_mm256_xor_si256(b,c),7);
    #define ROUND() QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15); QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
    ROUND(); ROUND(); ROUND(); ROUND(); ROUND();
    ROUND(); ROUND(); ROUND(); ROUND(); ROUND();
    #undef ROUND
    #undef QR
    x0=_mm256_add_epi32(x0,o0); x1=_mm256_add_epi32(x1,o1); x2=_mm256_add_epi32(x2,o2); x3=_mm256_add_epi32(x3,o3);
    x4=_mm256_add_epi32(x4,o4); x5=_mm256_add_epi32(x5,o5); x6=_mm256_add_epi32(x6,o6); x7=_mm256_add_epi32(x7,o7);
    x8=_mm256_add_epi32(x8,o8); x9=_mm256_add_epi32(x9,o9); x10=_mm256_add_epi32(x10,o10); x11=_mm256_add_epi32(x11,o11);
    x12=_mm256_add_epi32(x12,o12); x13=_mm256_add_epi32(x13,o13); x14=_mm256_add_epi32(x14,o14); x15=_mm256_add_epi32(x15,o15);
    __m256i g0[8]={x0,x1,x2,x3,x4,x5,x6,x7};
    __m256i g1[8]={x8,x9,x10,x11,x12,x13,x14,x15};
    transpose8(g0); transpose8(g1);
    for (int k=0;k<8;k++){
        __m256i s0=_mm256_loadu_si256((const __m256i*)(src+k*64));
        __m256i s1=_mm256_loadu_si256((const __m256i*)(src+k*64+32));
        _mm256_storeu_si256((__m256i*)(dst+k*64), _mm256_xor_si256(s0,g0[k]));
        _mm256_storeu_si256((__m256i*)(dst+k*64+32), _mm256_xor_si256(s1,g1[k]));
    }
    (void)counter_base;
}

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len, const unsigned int key[8], const unsigned int counter[4]);

int main(){
    size_t n = 40000UL*1024;
    uint8_t *pt=aligned_alloc(64,n), *ct=aligned_alloc(64,n);
    memset(pt,1,n);
    uint32_t st[16]={0x61707865,0x3320646e,0x79622d32,0x6b206574,1,2,3,4,5,6,7,8,0,9,10,11};
    __m256i base[16];
    for(int i=0;i<16;i++) base[i]=_mm256_set1_epi32(st[i]);

    /* warmup */
    uint32_t ctr=0;
    for(size_t off=0; off+512<=n && off<1<<16; off+=512){ base[12]=_mm256_set1_epi32(ctr); xor512(ct+off,pt+off,base,ctr); ctr+=8; }

    double t0=now(); int reps=3;
    for(int r=0;r<reps;r++){
        ctr=0;
        for(size_t off=0; off+512<=n; off+=512){ base[12]=_mm256_set1_epi32(ctr); xor512(ct+off,pt+off,base,ctr); ctr+=8; }
    }
    double dt=now()-t0;
    printf("our avx2 chacha %.1f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);

    unsigned int key[8]={1,2,3,4,5,6,7,8};
    unsigned int counter[4]={0,9,10,11};
    ChaCha20_ctr32(ct, pt, 1<<16, key, counter);
    t0=now();
    for(int r=0;r<reps;r++){ counter[0]=0; ChaCha20_ctr32(ct, pt, n, key, counter); }
    dt=now()-t0;
    printf("openssl chacha %.1f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);
    return 0;
}
