static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9;}

static volatile uint64_t sink;

/* bandwidth: streaming copy with nontemporal stores, result consumed */
static void *bw_worker(void *arg) {
    size_t n = (size_t)(256UL<<20);
    unsigned char *a = aligned_alloc(64, n);
    unsigned char *b = aligned_alloc(64, n);
    memset(a, 1, n);
    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        for (size_t i = 0; i + 64 <= n; i += 64) {
            __m256i v0 = _mm256_loadu_si256((const __m256i*)(a+i));
            __m256i v1 = _mm256_loadu_si256((const __m256i*)(a+i+32));
            _mm256_stream_si256((__m256i*)(b+i), v0);
            _mm256_stream_si256((__m256i*)(b+i+32), v1);
        }
        _mm_sfence();
    }
    double dt = now()-t0;
    sink += b[0] + b[n-1];
    printf("  stream copy thread traffic %.1f GB/s\n", reps*(2.0*n)/dt/1e9);
    free(a); free(b);
    return NULL;
}

typedef struct { unsigned char *pt, *ct; size_t off, len; unsigned int key[8]; unsigned int c0; unsigned int nonce[3]; int reps; } job;
static void *chacha_worker(void *arg) {
    job *j = arg;
    for (int r = 0; r < j->reps; r++) {
        unsigned int counter[4] = { j->c0, j->nonce[0], j->nonce[1], j->nonce[2] };
        ChaCha20_ctr32(j->ct + j->off, j->pt + j->off, j->len, j->key, counter);
    }
    return NULL;
}

int main() {
    printf("bandwidth:\n");
    pthread_t th[12];
    for (int nth = 1; nth <= 4; nth++) {
        double t0 = now();
        for (int i = 0; i < nth; i++) pthread_create(&th[i], NULL, bw_worker, NULL);
        for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
        printf("%d threads wall %.3f\n", nth, now()-t0);
    }

    size_t n = 40000UL*1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 1, n);
    unsigned int key[8] = {1,2,3,4,5,6,7,8};
    int reps = 4;
    for (int nth = 1; nth <= 8; nth++) {
        job jobs[12];
        size_t base = (n / nth) & ~63ull;
        size_t off = 0;
        for (int i = 0; i < nth; i++) {
            size_t len = (i == nth-1) ? n - off : base;
            jobs[i].pt = pt; jobs[i].ct = ct; jobs[i].off = off; jobs[i].len = len;
            memcpy(jobs[i].key, key, 32);
            jobs[i].c0 = (unsigned)(off/64);
            jobs[i].nonce[0]=1; jobs[i].nonce[1]=2; jobs[i].nonce[2]=3;
            jobs[i].reps = reps;
            off += len;
        }
        /* warmup */
        for (int i = 0; i < nth; i++) {
            unsigned int c[4]={jobs[i].c0,1,2,3};
            ChaCha20_ctr32(ct+jobs[i].off, pt+jobs[i].off, jobs[i].len > 65536 ? 65536 : jobs[i].len, key, c);
        }
        double t0 = now();
        for (int i = 0; i < nth; i++) pthread_create(&th[i], NULL, chacha_worker, &jobs[i]);
        for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
        double dt = now()-t0;
        sink += ct[0];
        printf("split %d threads: %.4f s/msg  %.0f MB/s\n", nth, dt/reps, reps*(n/1e6)/dt);
    }
    return 0;
}
