#include <OpenCL/opencl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9;}

static const char *SRC =
"uint rotl(uint x, uint n){ return (x<<n)|(x>>(32u-n)); }\n"
"__kernel void chacha(__global uint *out, __global const uint *in, uint blocks,\n"
"                     uint k0,uint k1,uint k2,uint k3,uint k4,uint k5,uint k6,uint k7,\n"
"                     uint ctr, uint n0,uint n1,uint n2){\n"
"  uint gid = get_global_id(0);\n"
"  if (gid >= blocks) return;\n"
"  uint x0=0x61707865u,x1=0x3320646eu,x2=0x79622d32u,x3=0x6b206574u;\n"
"  uint x4=k0,x5=k1,x6=k2,x7=k3,x8=k4,x9=k5,x10=k6,x11=k7;\n"
"  uint x12=ctr+gid, x13=n0, x14=n1, x15=n2;\n"
"  uint o0=x0,o1=x1,o2=x2,o3=x3,o4=x4,o5=x5,o6=x6,o7=x7,o8=x8,o9=x9,o10=x10,o11=x11,o12=x12,o13=x13,o14=x14,o15=x15;\n"
"  #define QR(a,b,c,d) a+=b; d=rotl(d^a,16u); c+=d; b=rotl(b^c,12u); a+=b; d=rotl(d^a,8u); c+=d; b=rotl(b^c,7u);\n"
"  for (int r=0;r<10;r++){ QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15); QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14); }\n"
"  #undef QR\n"
"  uint base = gid*16u;\n"
"  __global const uint *ip = in + base;\n"
"  __global uint *op = out + base;\n"
"  op[0]=ip[0]^(x0+o0); op[1]=ip[1]^(x1+o1); op[2]=ip[2]^(x2+o2); op[3]=ip[3]^(x3+o3);\n"
"  op[4]=ip[4]^(x4+o4); op[5]=ip[5]^(x5+o5); op[6]=ip[6]^(x6+o6); op[7]=ip[7]^(x7+o7);\n"
"  op[8]=ip[8]^(x8+o8); op[9]=ip[9]^(x9+o9); op[10]=ip[10]^(x10+o10); op[11]=ip[11]^(x11+o11);\n"
"  op[12]=ip[12]^(x12+o12); op[13]=ip[13]^(x13+o13); op[14]=ip[14]^(x14+o14); op[15]=ip[15]^(x15+o15);\n"
"}\n";

static void check(cl_int e, const char *w){ if(e!=CL_SUCCESS){ fprintf(stderr,"%s err %d\n", w, e); exit(1);} }

int main(){
    cl_platform_id plat; clGetPlatformIDs(1,&plat,NULL);
    cl_device_id devs[8]; cl_uint ndev; clGetDeviceIDs(plat, CL_DEVICE_TYPE_GPU, 8, devs, &ndev);
    /* pick AMD: last gpu */
    cl_device_id dev = devs[ndev-1];
    char name[128]; clGetDeviceInfo(dev, CL_DEVICE_NAME, sizeof(name), name, NULL);
    printf("using %s\n", name);
    cl_int err;
    cl_context ctx = clCreateContext(NULL,1,&dev,NULL,NULL,&err); check(err,"ctx");
    cl_command_queue q = clCreateCommandQueue(ctx, dev, 0, &err); check(err,"q");
    cl_program prog = clCreateProgramWithSource(ctx,1,&SRC,NULL,&err); check(err,"prog");
    err = clBuildProgram(prog,1,&dev,"-cl-fast-relaxed-math",NULL,NULL);
    if (err){ char log[8192]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,sizeof(log),log,NULL); fprintf(stderr,"%s\n",log); return 1; }
    cl_kernel k = clCreateKernel(prog,"chacha",&err); check(err,"kern");

    size_t n = 40000UL*1024;
    size_t blocks = n/64;
    unsigned char *pt = aligned_alloc(64,n);
    unsigned char *ct = aligned_alloc(64,n);
    memset(pt, 0x42, n);
    cl_mem in = clCreateBuffer(ctx, CL_MEM_READ_ONLY, n, NULL, &err);
    cl_mem out = clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, n, NULL, &err);
    check(err,"buf");

    uint32_t key[8]={1,2,3,4,5,6,7,8}; uint32_t ctr=1, n0=9,n1=10,n2=11;
    clSetKernelArg(k,0,sizeof(cl_mem),&out);
    clSetKernelArg(k,1,sizeof(cl_mem),&in);
    cl_uint b = (cl_uint)blocks;
    clSetKernelArg(k,2,sizeof(cl_uint),&b);
    for (int i=0;i<8;i++){ cl_uint v=key[i]; clSetKernelArg(k,3+i,sizeof(cl_uint),&v); }
    clSetKernelArg(k,11,sizeof(cl_uint),&ctr);
    clSetKernelArg(k,12,sizeof(cl_uint),&n0);
    clSetKernelArg(k,13,sizeof(cl_uint),&n1);
    clSetKernelArg(k,14,sizeof(cl_uint),&n2);

    /* warmup */
    clEnqueueWriteBuffer(q,in,CL_TRUE,0,n,pt,0,NULL,NULL);
    size_t g=blocks;
    clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL);
    clFinish(q);

    double t0=now(); int reps=4;
    for(int r=0;r<reps;r++){
        clEnqueueWriteBuffer(q,in,CL_FALSE,0,n,pt,0,NULL,NULL);
        clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL);
        clEnqueueReadBuffer(q,out,CL_FALSE,0,n,ct,0,NULL,NULL);
        clFinish(q);
    }
    double dt=now()-t0;
    printf("gpu incl transfer %.1f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);

    /* compute only, data resident */
    t0=now();
    for(int r=0;r<reps;r++){
        clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL);
        clFinish(q);
    }
    dt=now()-t0;
    printf("gpu compute only %.1f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);

    /* try Intel iGPU too */
    if (ndev>1){
        printf("(devices: %u)\n", ndev);
    }
    return 0;
}
