            unsigned int c[4]={ctr,1,2,3};
            ChaCha20_ctr32(ks, pt+off, len, key, c); /* this xors pt into ks: ks = pt XOR keystream. We want ct = pt XOR keystream = ks. Just stream-copy ks to ct. */
            unsigned char *d=ct+off;
            size_t i=0;
            for(; i+32<=len; i+=32){
                __m256i v=_mm256_loadu_si256((const __m256i*)(ks+i));
                _mm256_stream_si256((__m256i*)(d+i), v);
