            for(; i<len; i++) d[i]=ks[i];
            off+=len; ctr+=(uint32_t)(len/64);
        }
        _mm_sfence();
    }
    dt=now()-t0;
    s+=ct[1];
    printf("stream out %.0f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);
    (void)s;
    return 0;
}
