" op[8]=ip[8]^(x8+o8); op[9]=ip[9]^(x9+o9); op[10]=ip[10]^(x10+o10); op[11]=ip[11]^(x11+o11);\n"
" op[12]=ip[12]^(x12+o12); op[13]=ip[13]^(x13+o13); op[14]=ip[14]^(x14+o14); op[15]=ip[15]^(x15+o15);\n"
"}\n";

int main(){
    cl_platform_id plat; clGetPlatformIDs(1,&plat,NULL);
    cl_device_id devs[8]; cl_uint ndev; clGetDeviceIDs(plat,CL_DEVICE_TYPE_GPU,8,devs,&ndev);
    size_t n=40000UL*1024; n&=~255ull; size_t blocks4=n/256; /* 4 blocks per item */
    unsigned char *pt=aligned_alloc(4096,n), *ct=aligned_alloc(4096,n); memset(pt,0x42,n);
    for(cl_uint di=0; di<ndev; di++){
        cl_device_id dev=devs[di]; char name[128]; clGetDeviceInfo(dev,CL_DEVICE_NAME,sizeof(name),name,NULL);
        cl_bool unified=0; clGetDeviceInfo(dev,CL_DEVICE_HOST_UNIFIED_MEMORY,sizeof(unified),&unified,NULL);
        printf("== %s unified=%d\n", name, unified);
        cl_int err; cl_context ctx=clCreateContext(NULL,1,&dev,NULL,NULL,&err);
        cl_command_queue q=clCreateCommandQueue(ctx,dev,0,&err);
        cl_program prog=clCreateProgramWithSource(ctx,1,&SRC,NULL,&err);
        err=clBuildProgram(prog,1,&dev,"-cl-fast-relaxed-math",NULL,NULL);
        if(err){char log[4096]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,sizeof(log),log,NULL); fprintf(stderr,"%s\n",log); continue;}
        cl_kernel k=clCreateKernel(prog,"chacha",&err);
        /* device buffers */
        cl_mem in=clCreateBuffer(ctx,CL_MEM_READ_ONLY|CL_MEM_COPY_HOST_PTR,n,pt,&err);
        cl_mem out=clCreateBuffer(ctx,CL_MEM_WRITE_ONLY,n,NULL,&err);
        cl_uint b4=(cl_uint)blocks4; uint32_t key[8]={1,2,3,4,5,6,7,8}; cl_uint ctr=1,n0=9,n1=10,n2=11;
        clSetKernelArg(k,0,sizeof(cl_mem),&out); clSetKernelArg(k,1,sizeof(cl_mem),&in); clSetKernelArg(k,2,sizeof(cl_uint),&b4);
        for(int i=0;i<8;i++){cl_uint v=key[i]; clSetKernelArg(k,3+i,sizeof(cl_uint),&v);} 
        clSetKernelArg(k,11,sizeof(cl_uint),&ctr); clSetKernelArg(k,12,sizeof(cl_uint),&n0); clSetKernelArg(k,13,sizeof(cl_uint),&n1); clSetKernelArg(k,14,sizeof(cl_uint),&n2);
        size_t locals[]={64,128,256};
        for(int li=0;li<3;li++){
            size_t g=((blocks4+locals[li]-1)/locals[li])*locals[li]; size_t local=locals[li];
            clEnqueueNDRangeKernel(q,k,1,NULL,&g,&local,0,NULL,NULL); clFinish(q);
            double t0=now(); int reps=4;
            for(int r=0;r<reps;r++){clEnqueueNDRangeKernel(q,k,1,NULL,&g,&local,0,NULL,NULL); clFinish(q);} 
            double dt=now()-t0;
            printf("  local %zu compute %.0f MB/s\n", local, reps*(n/1e6)/dt);
        }
        /* zero copy via USE_HOST_PTR */
        cl_mem hin=clCreateBuffer(ctx,CL_MEM_READ_ONLY|CL_MEM_USE_HOST_PTR,n,pt,&err);
        cl_mem hout=clCreateBuffer(ctx,CL_MEM_WRITE_ONLY|CL_MEM_USE_HOST_PTR,n,ct,&err);
        printf("  use_host_ptr err %d\n", err);
        if(err==CL_SUCCESS){
            clSetKernelArg(k,0,sizeof(cl_mem),&hout); clSetKernelArg(k,1,sizeof(cl_mem),&hin);
            size_t g=((blocks4+255)/256)*256, local=256;
            clEnqueueNDRangeKernel(q,k,1,NULL,&g,&local,0,NULL,NULL); clFinish(q);
            double t0=now(); int reps=3;
            for(int r=0;r<reps;r++){clEnqueueNDRangeKernel(q,k,1,NULL,&g,&local,0,NULL,NULL); clFinish(q);} 
            double dt=now()-t0;
            printf("  zero-copy kernel %.0f MB/s per=%.4f\n", reps*(n/1e6)/dt, dt/reps);
        }
        clReleaseMemObject(in); clReleaseMemObject(out); clReleaseKernel(k); clReleaseProgram(prog); clReleaseCommandQueue(q); clReleaseContext(ctx);
    }
    return 0;
}
